import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"命令行搜索（lff）","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 为什么选择 lff","slug":"_1-为什么选择-lff","link":"#_1-为什么选择-lff","children":[]},{"level":2,"title":"2. 安装与 PATH 配置","slug":"_2-安装与-path-配置","link":"#_2-安装与-path-配置","children":[]},{"level":2,"title":"3. 交互界面与操作按键","slug":"_3-交互界面与操作按键","link":"#_3-交互界面与操作按键","children":[{"level":3,"title":"常用交互快捷键","slug":"常用交互快捷键","link":"#常用交互快捷键","children":[]}]},{"level":2,"title":"4. 非交互式搜索","slug":"_4-非交互式搜索","link":"#_4-非交互式搜索","children":[]},{"level":2,"title":"5. 预填关键词与管道传参","slug":"_5-预填关键词与管道传参","link":"#_5-预填关键词与管道传参","children":[]},{"level":2,"title":"6. 多选标记与批量输出","slug":"_6-多选标记与批量输出","link":"#_6-多选标记与批量输出","children":[]},{"level":2,"title":"7. Shell 脚本与命令联动实战","slug":"_7-shell-脚本与命令联动实战","link":"#_7-shell-脚本与命令联动实战","children":[{"level":3,"title":"PowerShell 常用联动","slug":"powershell-常用联动","link":"#powershell-常用联动","children":[]},{"level":3,"title":"CMD / Batch 批处理联动","slug":"cmd-batch-批处理联动","link":"#cmd-batch-批处理联动","children":[]}]},{"level":2,"title":"8. 使用局限与设计边界","slug":"_8-使用局限与设计边界","link":"#_8-使用局限与设计边界","children":[]}],"relativePath":"zh-CN/user-guide/cli.md","filePath":"zh-CN/user-guide/cli.md","lastUpdated":1791112464000}`),a={name:`zh-CN/user-guide/cli.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="命令行搜索-lff" tabindex="-1">命令行搜索（lff） <a class="header-anchor" href="#命令行搜索-lff" aria-label="Permalink to “命令行搜索（lff）”">​</a></h1><p>Lertaro 附带了一个轻量的命令行伴侣工具 <strong><code>lff</code></strong>（Lertaro Fuzzy Finder），一个专为终端与脚本开发者打造的交互式模糊查找工具。它直接通过本地具名管道与 Lertaro App 进程通信，直接复用后台已构建的内存索引，无需在终端中重新扫描磁盘。</p><h2 id="_1-为什么选择-lff" tabindex="-1">1. 为什么选择 lff <a class="header-anchor" href="#_1-为什么选择-lff" aria-label="Permalink to “1. 为什么选择 lff”">​</a></h2><ul><li><strong>共享索引，零 I/O 延迟</strong>：与 <code>fzf</code> 或 <code>find</code> 等传统工具每次从头遍历磁盘不同，<code>lff</code> 毫秒级直接查询 Lertaro 维护的千万级文件索引树。</li><li><strong>一致的搜索语法</strong>：完全继承 Lertaro 的模糊跳跃匹配、中文拼音别名匹配与修饰符语法（详见<a href="./search-syntax.html"><strong>搜索语法</strong></a>）。</li><li><strong>快速失败机制</strong>：<code>lff</code> 会自动检测 Lertaro App 的运行状态。若主程序未启动，会立即向 <code>stderr</code> 打印错误提示并退出，绝不阻塞终端会话。</li></ul><h2 id="_2-安装与-path-配置" tabindex="-1">2. 安装与 PATH 配置 <a class="header-anchor" href="#_2-安装与-path-配置" aria-label="Permalink to “2. 安装与 PATH 配置”">​</a></h2><p><code>lff.exe</code> 随 Lertaro 主程序一同打包分发：</p><ul><li><strong>安装版</strong>：在安装向导的任务选择界面中勾选<strong>将 lff 命令行搜索工具添加到 PATH</strong>，即可在任意终端窗口中直接输入 <code>lff</code> 运行。</li><li><strong>便携版</strong>：将解压目录手动添加至系统的用户或系统 <code>PATH</code> 环境变量中。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>修改 PATH 后，请新打开一个终端窗口以使环境变量生效；当前已打开的终端无法感知外部环境变量的变更。</p></div><h2 id="_3-交互界面与操作按键" tabindex="-1">3. 交互界面与操作按键 <a class="header-anchor" href="#_3-交互界面与操作按键" aria-label="Permalink to “3. 交互界面与操作按键”">​</a></h2><p>在终端中输入 <code>lff</code> 并回车，即可进入全屏交互式搜索界面：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lff</span></span></code></pre></div><h3 id="常用交互快捷键" tabindex="-1">常用交互快捷键 <a class="header-anchor" href="#常用交互快捷键" aria-label="Permalink to “常用交互快捷键”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">按键</th><th style="text-align:left;">功能说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>直接输入字符</strong></td><td style="text-align:left;">实时模糊过滤搜索结果（支持中文拼音首字母与全拼）。</td></tr><tr><td style="text-align:left;"><code>↑</code> / <code>↓</code></td><td style="text-align:left;">向上 / 向下移动当前高亮项。</td></tr><tr><td style="text-align:left;"><code>Page Up</code> / <code>Page Down</code></td><td style="text-align:left;">向上 / 向下快速翻页。</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code></td><td style="text-align:left;">在底部搜索输入框中左右移动光标。</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">切换选中/取消选中当前高亮项（被多选标记的行会带有 <code>*</code> 标识）。</td></tr><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">将所有标记的路径（若无标记则输出当前高亮项路径）输出至 <code>stdout</code> 并退出。</td></tr><tr><td style="text-align:left;"><code>Esc</code> 或 <code>Ctrl+C</code></td><td style="text-align:left;">不输出任何内容，直接安全退出。</td></tr></tbody></table><h2 id="_4-非交互式搜索" tabindex="-1">4. 非交互式搜索 <a class="header-anchor" href="#_4-非交互式搜索" aria-label="Permalink to “4. 非交互式搜索”">​</a></h2><p>当脚本只需要搜索结果、不需要打开交互界面时，可以使用 <code>--search</code>：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 输出最多 20 条匹配路径</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;report&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 先对完整结果集排序，再保留前 50 条</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;report&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 只搜索指定目录及其子目录中的文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;report&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --files</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;D:\\Documents&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 只搜索文件夹</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;report&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --folders</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 输出包含结果元数据的单个紧凑 JSON 数组</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;report&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>完整结果集会先排序，再应用 <code>--limit</code>。未指定 <code>--limit</code> 时最多输出 20 条结果。普通输出每行一个路径；使用 <code>--json</code> 时输出一个 JSON 数组，而不是 NDJSON。每个 JSON 项包含名称、路径、是否为目录、驱动器、属性、大小，以及创建、修改和访问时间。该模式使用与交互界面相同的搜索语法，并要求 Lertaro App 正在运行。</p><p><code>--files</code> 与 <code>--folders</code> 不能同时使用。<code>--path</code> 会将搜索范围限制为指定目录及其所有子目录。</p><h2 id="_5-预填关键词与管道传参" tabindex="-1">5. 预填关键词与管道传参 <a class="header-anchor" href="#_5-预填关键词与管道传参" aria-label="Permalink to “5. 预填关键词与管道传参”">​</a></h2><p>你可以直接在启动参数中指定初始搜索词，或通过标准输入管道传入：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 参数预填</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 管道传入</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> lff</span></span></code></pre></div><p>两种方式都会自动以 <code>report</code> 作为初始过滤词打开交互界面，你可以继续键盘微调或直接按 <code>Enter</code> 确认输出。</p><h2 id="_6-多选标记与批量输出" tabindex="-1">6. 多选标记与批量输出 <a class="header-anchor" href="#_6-多选标记与批量输出" aria-label="Permalink to “6. 多选标记与批量输出”">​</a></h2><p>按下 <code>Tab</code> 键可以标记当前行。这一点值得注意，<strong>标记状态在更改搜索关键词后依然会被保留</strong>。</p><p>这意味着你可以先搜索 <code>doc</code> 标记几个 Word 文档，再清空输入 <code>pdf</code> 标记几个 PDF 报表，最后统一按下 <code>Enter</code> 键，<code>lff</code> 会将所有跨多次搜索选中的文件路径以换行符分隔逐行输出至标准输出。</p><h2 id="_7-shell-脚本与命令联动实战" tabindex="-1">7. Shell 脚本与命令联动实战 <a class="header-anchor" href="#_7-shell-脚本与命令联动实战" aria-label="Permalink to “7. Shell 脚本与命令联动实战”">​</a></h2><p><code>lff</code> 的 TUI 界面直接绘制在控制台缓冲区，不会污染标准输出流。只有用户最终确认选中的文件路径才会写入 <code>stdout</code>，因此可以与各类 Shell 语法组合：</p><h3 id="powershell-常用联动" tabindex="-1">PowerShell 常用联动 <a class="header-anchor" href="#powershell-常用联动" aria-label="Permalink to “PowerShell 常用联动”">​</a></h3><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 使用 VS Code 打开检索到的文件</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code (lff)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 获取选中路径并赋值给变量</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$target </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lff; cd $target</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 将检索结果作为对象传递给后续管道</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lff </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Get-Item</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Name</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Length</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LastWriteTime</span></span></code></pre></div><h3 id="cmd-batch-批处理联动" tabindex="-1">CMD / Batch 批处理联动 <a class="header-anchor" href="#cmd-batch-批处理联动" aria-label="Permalink to “CMD / Batch 批处理联动”">​</a></h3><div class="language-cmd"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">:: 使用 for 循环逐行处理选中的路径</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;delims=&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %i in (&#39;lff&#39;) do code &quot;%i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><h2 id="_8-使用局限与设计边界" tabindex="-1">8. 使用局限与设计边界 <a class="header-anchor" href="#_8-使用局限与设计边界" aria-label="Permalink to “8. 使用局限与设计边界”">​</a></h2><ul><li><strong>依赖前台 App</strong>：<code>lff</code> 自身不包含索引逻辑，必须在 Lertaro App 运行期间使用。</li><li><strong>无图形预览</strong>：命令行工具专注于路径输出与管道组合，如需富文本/音视频即时预览，请在 GUI 窗口中使用<a href="./actions-and-preview.html"><strong>动作菜单与预览</strong></a>。</li></ul>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};